#include <iostream>
#include <list>
#include <optional>
#include <sstream>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

class LruCache
{
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {}

    // Returns the evicted key, if any.
    std::optional<std::string> put(const std::string& key, const std::string& value, bool& updated)
    {
        auto found = index_.find(key);
        if (found != index_.end())
        {
            found->second->second = value;
            entries_.splice(entries_.begin(), entries_, found->second);
            updated = true;
            return std::nullopt;
        }
        updated = false;
        std::optional<std::string> evicted;
        if (entries_.size() == capacity_) evicted = evictOne();
        entries_.emplace_front(key, value);
        index_[key] = entries_.begin();
        return evicted;
    }

    std::optional<std::string> get(const std::string& key)
    {
        auto found = index_.find(key);
        if (found == index_.end())
        {
            ++misses_;
            return std::nullopt;
        }
        ++hits_;
        entries_.splice(entries_.begin(), entries_, found->second);
        return found->second->second;
    }

    std::optional<std::string> peek(const std::string& key) const
    {
        auto found = index_.find(key);
        if (found == index_.end()) return std::nullopt;
        return found->second->second;
    }

    bool erase(const std::string& key)
    {
        auto found = index_.find(key);
        if (found == index_.end()) return false;
        entries_.erase(found->second);
        index_.erase(found);
        return true;
    }

    std::vector<std::string> resize(std::size_t capacity)
    {
        capacity_ = capacity;
        std::vector<std::string> evicted;
        while (entries_.size() > capacity_) evicted.push_back(evictOne());
        return evicted;
    }

    void clear()
    {
        entries_.clear();
        index_.clear();
    }

    std::vector<std::string> keys() const
    {
        std::vector<std::string> out;
        for (const auto& entry : entries_) out.push_back(entry.first);
        return out;
    }

    std::string stats() const
    {
        return "hits " + std::to_string(hits_) + ", misses " + std::to_string(misses_) + ", evictions " + std::to_string(evictions_) +
               ", size " + std::to_string(entries_.size()) + "/" + std::to_string(capacity_);
    }

private:
    std::string evictOne()
    {
        std::string key = entries_.back().first;
        index_.erase(key);
        entries_.pop_back();
        ++evictions_;
        return key;
    }

    using Entries = std::list<std::pair<std::string, std::string>>;
    Entries entries_;
    std::unordered_map<std::string, Entries::iterator> index_;
    std::size_t capacity_;
    long long hits_ = 0, misses_ = 0, evictions_ = 0;
};

static std::vector<std::string> words(const std::string& line)
{
    std::istringstream in(line);
    std::vector<std::string> out;
    for (std::string w; in >> w;) out.push_back(w);
    return out;
}

static std::optional<std::size_t> parseCapacity(const std::string& text)
{
    if (text.empty() || text.size() > 7) return std::nullopt;
    for (char c : text)
        if (c < '0' || c > '9') return std::nullopt;
    std::size_t n = std::stoul(text);
    if (n < 1 || n > 1000000) return std::nullopt;
    return n;
}

static std::string joined(const std::vector<std::string>& items)
{
    std::string out;
    for (std::size_t i = 0; i < items.size(); ++i) out += (i ? ", " : "") + items[i];
    return out;
}

static const char* const kCapacityError = "error: capacity must be a whole number from 1 to 1000000";

int main()
{
    std::string line;
    std::vector<std::string> first;
    while (first.empty() && std::getline(std::cin, line)) first = words(line);
    if (first.size() != 2 || first[0] != "capacity")
    {
        std::cout << "error: the first line must be 'capacity <n>'\n";
        return 0;
    }
    auto capacity = parseCapacity(first[1]);
    if (!capacity)
    {
        std::cout << kCapacityError << '\n';
        return 0;
    }

    LruCache cache(*capacity);
    const std::unordered_map<std::string, std::pair<std::size_t, std::string>> usage{
        { "put", { 3, "put <key> <value>" } }, { "get", { 2, "get <key>" } }, { "peek", { 2, "peek <key>" } },
        { "del", { 2, "del <key>" } }, { "list", { 1, "list" } }, { "stats", { 1, "stats" } },
        { "resize", { 2, "resize <n>" } }, { "clear", { 1, "clear" } } };

    while (std::getline(std::cin, line))
    {
        std::vector<std::string> w = words(line);
        if (w.empty()) continue;
        auto known = usage.find(w[0]);
        if (known == usage.end())
        {
            std::cout << "error: unknown command '" << w[0] << "'\n";
            continue;
        }
        if (w.size() != known->second.first)
        {
            std::cout << "error: usage: " << known->second.second << '\n';
            continue;
        }

        const std::string& cmd = w[0];
        if (cmd == "put")
        {
            bool updated = false;
            auto evicted = cache.put(w[1], w[2], updated);
            if (updated) std::cout << "updated\n";
            else if (evicted) std::cout << "ok (evicted " << *evicted << ")\n";
            else std::cout << "ok\n";
        }
        else if (cmd == "get")
        {
            auto value = cache.get(w[1]);
            std::cout << (value ? *value : "miss") << '\n';
        }
        else if (cmd == "peek")
        {
            auto value = cache.peek(w[1]);
            std::cout << (value ? *value : "miss") << '\n';
        }
        else if (cmd == "del")
        {
            std::cout << (cache.erase(w[1]) ? "deleted" : "missing") << '\n';
        }
        else if (cmd == "list")
        {
            std::cout << '[' << joined(cache.keys()) << "]\n";
        }
        else if (cmd == "stats")
        {
            std::cout << cache.stats() << '\n';
        }
        else if (cmd == "resize")
        {
            auto n = parseCapacity(w[1]);
            if (!n)
            {
                std::cout << kCapacityError << '\n';
                continue;
            }
            auto evicted = cache.resize(*n);
            std::cout << "resized to " << *n;
            if (!evicted.empty()) std::cout << " (evicted " << joined(evicted) << ")";
            std::cout << '\n';
        }
        else
        {
            cache.clear();
            std::cout << "cleared\n";
        }
    }
}
